it('refuses a value quoted in a message that has no detail section at all', () => {
    // Class 22 errors put the offending value in the *primary* message, so
    // none of the row-data markers precede it. Captured live, with the
    // value crafted to read as schema. Only the anchoring stops this.
    const record = redactPrismaLogEvent('error', {
        timestamp: new Date('2026-08-05T10:00:00Z'),
        message:
            'Raw query failed. Code: `22P02`. Message: `ERROR: invalid input ' +
            'syntax for type integer: "relation \\"VICTIM_SECRET\\" constraint ' +
            '\\"TOKEN_9f3a\\""`',
        target: '$queryRaw',
    });

    const serialized = JSON.stringify(record);
    expect(serialized).not.toContain('VICTIM_SECRET');
    expect(serialized).not.toContain('TOKEN_9f3a');
    expect(record.relation).toBeNull();
    expect(record.constraint).toBeNull();
    expect(record.code).toBe('22P02');
});

